struct Params {
    dstSize: vec2u,
    srcSize: vec2u,
    offset: vec2f,
    scale: vec2f,
};

@group(0) @binding(1) var<storage, read_write> out_z: array<u32>;
@group(0) @binding(2) var<uniform> params: Params;

fn gx_z24(depth: f32) -> u32 {
    return min(u32(clamp(1.0 - depth, 0.0, 1.0) * 16777215.0 + 0.5), 0x00ffffffu);
}

@group(0) @binding(0) var src: texture_depth_2d;

fn load_depth(coord: vec2i) -> f32 {
    return textureLoad(src, coord, 0);
}

@compute @workgroup_size(8, 8, 1)
fn cs_main(@builtin(global_invocation_id) id: vec3u) {
    if (id.x >= params.dstSize.x || id.y >= params.dstSize.y) {
        return;
    }

    let dstCenter = vec2f(vec2u(id.xy)) + vec2f(0.5, 0.5);
    let srcPixel = clamp(vec2i(floor(params.offset + dstCenter * params.scale)), vec2i(0, 0),
                         vec2i(params.srcSize) - vec2i(1, 1));
    let depth = load_depth(srcPixel);
    out_z[id.y * params.dstSize.x + id.x] = gx_z24(depth);
}

@group(0) @binding(0) var src_samp: sampler;
@group(0) @binding(1) var src: texture_2d<f32>;

struct Uniforms {
    offset: vec2f,
    scale: vec2f,
    opaqueAlpha: u32,
    quantize: u32,
    lineStep: f32,
    filterTaps: u32,
    clampTop: f32,
    clampBottom: f32,
};
@group(0) @binding(2) var<uniform> ubuf: Uniforms;

struct VertexOutput {
    @builtin(position) pos: vec4f,
    @location(0) uv: vec2f,
};

var<private> positions: array<vec2f, 3> = array(
    vec2f(-1.0, 1.0),
    vec2f(-1.0, -3.0),
    vec2f(3.0, 1.0),
);
var<private> uvs: array<vec2f, 3> = array(
    vec2f(0.0, 0.0),
    vec2f(0.0, 2.0),
    vec2f(2.0, 0.0),
);

@vertex fn vs_main(@builtin(vertex_index) vi: u32) -> VertexOutput {
    var out: VertexOutput;
    out.pos = vec4f(positions[vi], 0.0, 1.0);
    out.uv = uvs[vi] * ubuf.scale + ubuf.offset;
    return out;
}

fn sample_efb(uv: vec2f) -> vec4f {
    var c = textureSampleLevel(src, src_samp, uv, 0.0);
    // Vertical copy filter (GXSetCopyFilter): weighted sum (taps out of 64) of the line above,
    // this line and the line below, saturating at 1, before the format conversion; RGB only
    // (alpha is copied from this line). With GXSetCopyClamp the neighbour lines of the source
    // rectangle's first / last line are that line itself.
    // The neighbour taps are one row of the copy source away: exactly the hardware's lines at
    // native resolution. Above it, taps one EFB line (several rows) apart would add sharp copies
    // of the image a few pixels above and below (ghost outlines); one row keeps the filter's
    // softening at the render resolution, as everything else scales.
    if (ubuf.filterTaps != 0u) {
        let rowStep = 1.0 / f32(textureDimensions(src).y);
        let wa = f32(ubuf.filterTaps & 0xffu);
        let wc = f32((ubuf.filterTaps >> 8u) & 0xffu);
        let wb = f32((ubuf.filterTaps >> 16u) & 0xffu);
        let above = textureSampleLevel(src, src_samp, vec2f(uv.x, max(uv.y - rowStep, ubuf.clampTop)), 0.0).rgb;
        let below = textureSampleLevel(src, src_samp, vec2f(uv.x, min(uv.y + rowStep, ubuf.clampBottom)), 0.0).rgb;
        c = vec4f(min((above * wa + c.rgb * wc + below * wb) / 64.0, vec3f(1.0)), c.a);
    }
    return vec4f(c.rgb, select(c.a, 1.0, ubuf.opaqueAlpha != 0u));
}

fn intensity(rgb: vec3f) -> f32 {
    // ITU-R BT.601 luma coefficients
    return dot(rgb, vec3f(0.257, 0.504, 0.098)) + 16.0 / 255.0;
}

fn quantize4(v: f32) -> f32 {
    return floor(v * 16.0) / 15.0;
}

// The top n bits of an 8-bit channel, expanded back to 8 bits by bit replication (as the texture
// unit decodes RGB565/RGB5A3 texels).
fn bits8(v: f32, n: u32) -> f32 {
    let x = (u32(round(clamp(v, 0.0, 1.0) * 255.0)) >> (8u - n)) << (8u - n);
    return f32(x | (x >> n) | (x >> (2u * n))) / 255.0;
}

// The n-bit level k widened like bits8: x | x >> n | x >> 2n with x = k << (8 - n).
fn widen8(k: f32, lev: f32, step: f32) -> f32 {
    let x = k * step;
    return x + floor(x / lev) + floor(x / (lev * lev));
}

// 0190 (GX_AURORA_ACCURACY_EFB_SMOOTH, quantize == 2): the average of bits8 over a smooth input
// instead of its steps. The EFB holds 6-bit values, so keeping n bits drops 6 - n of them, on
// average 2 * (2^(6 - n) - 1) of 255 (2 for 5 bits, 6 for 4, 0 for 6): the ramp through the widened
// n-bit levels, shifted by that, keeps the copy's brightness and tint without its bands.
fn smooth8(v: f32, n: u32) -> f32 {
    let lev = f32(1u << n);
    let step = 256.0 / lev;
    let t = (clamp(v, 0.0, 1.0) * 255.0 - 2.0 * (64.0 / lev - 1.0)) / step;
    let k = clamp(floor(t), 0.0, lev - 1.0);
    let k1 = min(k + 1.0, lev - 1.0);
    return mix(widen8(k, lev, step), widen8(k1, lev, step), clamp(t - k, 0.0, 1.0)) / 255.0;
}

@fragment fn fs_main(in: VertexOutput) -> @location(0) vec4f {
    return sample_efb(in.uv);
}

