@group(0) @binding(0) var src: texture_2d<f32>;
@vertex fn vs_main(@builtin(vertex_index) i: u32) -> @builtin(position) vec4f {
  let uv = vec2f(f32((i << 1u) & 2u), f32(i & 2u));
  return vec4f(uv * 2.0 - 1.0, 0.0, 1.0);
}
@fragment fn fs_main(@builtin(position) pos: vec4f) -> @location(0) vec4f {
  let c = textureLoad(src, vec2i(pos.xy), 0);
  let q8 = vec4i(round(clamp(c, vec4f(0.0), vec4f(1.0)) * 255.0));
  let hi = q8 >> vec4u(2u);
  let wid = (hi << vec4u(2u)) | (hi >> vec4u(4u));
  var rgb = q8.rgb;
  let qn = rgb >> vec3u(2u);
  let out = (qn << vec3u(2u)) | (qn >> vec3u(4u));
  return vec4f(vec4i(out, wid.a)) / 255.0;
}

@group(0) @binding(0) var src: texture_2d<f32>;
@vertex fn vs_main(@builtin(vertex_index) i: u32) -> @builtin(position) vec4f {
  let uv = vec2f(f32((i << 1u) & 2u), f32(i & 2u));
  return vec4f(uv * 2.0 - 1.0, 0.0, 1.0);
}
@fragment fn fs_main(@builtin(position) pos: vec4f) -> @location(0) vec4f {
  let c = textureLoad(src, vec2i(pos.xy), 0);
  let q8 = vec4i(round(clamp(c, vec4f(0.0), vec4f(1.0)) * 255.0));
  let hi = q8 >> vec4u(2u);
  let wid = (hi << vec4u(2u)) | (hi >> vec4u(4u));
  var rgb = q8.rgb;
  let dp = vec2u(pos.xy) & vec2u(1u);
  let dq = i32(select(select(0u, 2u, dp.x == 1u), select(3u, 1u, dp.x == 1u), dp.y == 1u));
  rgb = select(rgb - (rgb >> vec3u(6u)) + vec3i(dq), rgb, q8.rgb == wid.rgb);
  let qn = rgb >> vec3u(2u);
  let out = (qn << vec3u(2u)) | (qn >> vec3u(4u));
  return vec4f(vec4i(out, wid.a)) / 255.0;
}

